"use client";

import type { ButtonHTMLAttributes } from "react";
import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";

export interface SlideToggleSwitchProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "defaultValue"> {
  defaultChecked?: boolean;
  size?: number;
  damping?: number;
}

export function SlideToggleSwitch({
  defaultChecked = false,
  size = 1,
  damping = 24,
  disabled = false,
  className = "",
  ...props
}: SlideToggleSwitchProps) {
  const prefersReducedMotion = useReducedMotion() ?? false;
  const [checked, setChecked] = useState(defaultChecked);

  const width = 72 * size;
  const height = 40 * size;
  const thumb = 30 * size;
  const x = width - thumb - 5 * size;

  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-label="Toggle setting"
      disabled={disabled}
      onClick={() => setChecked((current) => !current)}
      className={`relative inline-flex items-center rounded-full border transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-200/80 focus-visible:ring-offset-4 focus-visible:ring-offset-slate-950 disabled:cursor-not-allowed disabled:opacity-45 ${
        checked
          ? "border-cyan-200/30 bg-cyan-300/18"
          : "border-white/10 bg-white/[0.06]"
      } ${className}`}
      style={{ width, height }}
      {...props}
    >
      <span
        className={`absolute inset-[1px] rounded-full ${
          checked
            ? "bg-[linear-gradient(90deg,rgba(34,211,238,0.22),rgba(125,211,252,0.38))]"
            : "bg-[linear-gradient(90deg,rgba(255,255,255,0.04),rgba(255,255,255,0.02))]"
        }`}
      />
      <motion.span
        className="absolute inset-y-1 left-1 rounded-full bg-cyan-200/15"
        animate={{
          width: checked ? width - 8 * size : thumb + 10 * size,
          opacity: checked ? 1 : 0.45,
        }}
        transition={
          prefersReducedMotion
            ? { duration: 0 }
            : { duration: 0.22, ease: [0.16, 1, 0.3, 1] }
        }
      />
      <motion.span
        className="absolute left-[4px] top-[4px] flex items-center justify-center rounded-full bg-white text-slate-950 shadow-[0_12px_28px_-18px_rgba(15,23,42,0.85)]"
        style={{ width: thumb, height: thumb }}
        animate={{ x: checked ? x : 0 }}
        transition={
          prefersReducedMotion
            ? { duration: 0 }
            : { type: "spring", stiffness: 340, damping }
        }
      >
        <motion.span
          animate={{ opacity: checked ? 1 : 0, scale: checked ? 1 : 0.7 }}
          transition={{ duration: prefersReducedMotion ? 0 : 0.16 }}
        >
          ✓
        </motion.span>
        <motion.span
          className="absolute"
          animate={{ opacity: checked ? 0 : 1, scale: checked ? 0.7 : 1 }}
          transition={{ duration: prefersReducedMotion ? 0 : 0.16 }}
        >
          •
        </motion.span>
      </motion.span>
    </button>
  );
}

"use client";

import type { HTMLAttributes, ReactNode } from "react";
import { useMemo, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

export interface TabUnderlineItem {
  id: string;
  label: string;
  content: ReactNode;
}

export interface TabUnderlineFollowerProps extends HTMLAttributes<HTMLDivElement> {
  tabs: TabUnderlineItem[];
  underlineStyle?: "line" | "pill";
  defaultTabId?: string;
  disabled?: boolean;
}

export function TabUnderlineFollower({
  tabs,
  underlineStyle = "line",
  defaultTabId,
  disabled = false,
  className = "",
  ...props
}: TabUnderlineFollowerProps) {
  const prefersReducedMotion = useReducedMotion() ?? false;
  const initialTab = useMemo(
    () => defaultTabId ?? tabs[0]?.id ?? "",
    [defaultTabId, tabs]
  );
  const [activeTab, setActiveTab] = useState(initialTab);
  const tabsRef = useRef<Array<HTMLButtonElement | null>>([]);
  const activeIndex = Math.max(
    0,
    tabs.findIndex((tab) => tab.id === activeTab)
  );
  const activeItem = tabs[activeIndex];

  const focusTab = (index: number) => {
    const nextIndex = (index + tabs.length) % tabs.length;
    setActiveTab(tabs[nextIndex].id);
    tabsRef.current[nextIndex]?.focus();
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled || tabs.length === 0) {
      return;
    }

    if (event.key === "ArrowRight") {
      event.preventDefault();
      focusTab(activeIndex + 1);
    }

    if (event.key === "ArrowLeft") {
      event.preventDefault();
      focusTab(activeIndex - 1);
    }

    if (event.key === "Home") {
      event.preventDefault();
      focusTab(0);
    }

    if (event.key === "End") {
      event.preventDefault();
      focusTab(tabs.length - 1);
    }
  };

  return (
    <div className={`flex flex-col gap-6 ${className}`} {...props}>
      <div
        role="tablist"
        aria-label="Tab underline follower"
        onKeyDown={handleKeyDown}
        className="flex flex-wrap gap-2 rounded-[1.6rem] border border-white/10 bg-slate-950/85 p-2"
      >
        {tabs.map((tab, index) => {
          const isActive = tab.id === activeTab;

          return (
            <button
              key={tab.id}
              ref={(node) => {
                tabsRef.current[index] = node;
              }}
              type="button"
              role="tab"
              id={`${tab.id}-tab`}
              aria-selected={isActive}
              aria-controls={`${tab.id}-panel`}
              tabIndex={isActive ? 0 : -1}
              disabled={disabled}
              onClick={() => setActiveTab(tab.id)}
              className={`relative rounded-full px-4 py-2.5 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-200/80 focus-visible:ring-offset-2 focus-visible:ring-offset-slate-950 ${
                isActive ? "text-white" : "text-zinc-400 hover:text-zinc-100"
              }`}
            >
              {isActive ? (
                underlineStyle === "pill" ? (
                  prefersReducedMotion ? (
                    <span className="absolute inset-0 rounded-full bg-white/10" />
                  ) : (
                    <motion.span
                      layoutId="tab-underline-pill"
                      className="absolute inset-0 rounded-full bg-white/10"
                      transition={{ type: "spring", stiffness: 360, damping: 28 }}
                    />
                  )
                ) : prefersReducedMotion ? (
                  <span className="absolute inset-x-3 bottom-1 h-0.5 rounded-full bg-cyan-200" />
                ) : (
                  <motion.span
                    layoutId="tab-underline-line"
                    className="absolute inset-x-3 bottom-1 h-0.5 rounded-full bg-cyan-200"
                    transition={{ type: "spring", stiffness: 380, damping: 30 }}
                  />
                )
              ) : null}
              <span className="relative z-10">{tab.label}</span>
            </button>
          );
        })}
      </div>

      <div className="min-h-44 rounded-[1.8rem] border border-white/10 bg-white/[0.03] p-6">
        {prefersReducedMotion ? (
          <div
            role="tabpanel"
            id={`${activeItem?.id ?? "tab"}-panel`}
            aria-labelledby={`${activeItem?.id ?? "tab"}-tab`}
            className="text-sm leading-7 text-zinc-300"
          >
            {activeItem?.content}
          </div>
        ) : (
          <AnimatePresence mode="wait" initial={false}>
            <motion.div
              key={activeItem?.id}
              role="tabpanel"
              id={`${activeItem?.id ?? "tab"}-panel`}
              aria-labelledby={`${activeItem?.id ?? "tab"}-tab`}
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}
              className="text-sm leading-7 text-zinc-300"
            >
              {activeItem?.content}
            </motion.div>
          </AnimatePresence>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type HTMLMotionProps,
} from "motion/react";

interface Ripple {
  id: number;
  x: number;
  y: number;
  size: number;
}

export interface RipplePressButtonProps
  extends Omit<HTMLMotionProps<"button">, "children"> {
  label?: string;
  rippleSize?: number;
  duration?: number;
}

export function RipplePressButton({
  label = "Ping Action",
  rippleSize = 180,
  duration = 220,
  disabled = false,
  className = "",
  ...props
}: RipplePressButtonProps) {
  const prefersReducedMotion = useReducedMotion() ?? false;
  const [ripples, setRipples] = useState<Ripple[]>([]);
  const [flashKey, setFlashKey] = useState(0);
  const nextId = useRef(0);

  useEffect(() => {
    return () => {
      setRipples([]);
    };
  }, []);

  const spawnRipple = (x: number, y: number) => {
    if (disabled) {
      return;
    }

    if (prefersReducedMotion) {
      setFlashKey((current) => current + 1);
      return;
    }

    const id = nextId.current++;
    setRipples((current) => [...current, { id, x, y, size: rippleSize }]);

    window.setTimeout(() => {
      setRipples((current) => current.filter((ripple) => ripple.id !== id));
    }, duration + 40);
  };

  const handlePointerDown = (event: React.PointerEvent<HTMLButtonElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    spawnRipple(event.clientX - rect.left, event.clientY - rect.top);
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (event.repeat || (event.key !== "Enter" && event.key !== " ")) {
      return;
    }

    const rect = event.currentTarget.getBoundingClientRect();
    spawnRipple(rect.width / 2, rect.height / 2);
  };

  return (
    <motion.button
      type="button"
      disabled={disabled}
      onPointerDown={handlePointerDown}
      onKeyDown={handleKeyDown}
      className={`relative inline-flex min-h-14 items-center justify-center overflow-hidden rounded-2xl border border-white/10 bg-slate-950 px-6 py-4 text-sm font-semibold tracking-[0.08em] text-zinc-100 shadow-[0_20px_40px_-28px_rgba(15,23,42,0.9)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-200/80 focus-visible:ring-offset-4 focus-visible:ring-offset-slate-950 disabled:cursor-not-allowed disabled:opacity-40 ${className}`}
      whileHover={disabled ? undefined : { scale: 1.01 }}
      whileTap={disabled ? undefined : { scale: 0.97 }}
      transition={{ type: "spring", stiffness: 360, damping: 26 }}
      {...props}
    >
      <span className="absolute inset-0 bg-[linear-gradient(135deg,rgba(56,189,248,0.16),transparent_40%,rgba(236,72,153,0.18))]" />

      <AnimatePresence>
        {ripples.map((ripple) => (
          <motion.span
            key={ripple.id}
            className="pointer-events-none absolute rounded-full bg-[radial-gradient(circle,rgba(255,255,255,0.85),rgba(34,211,238,0.45),transparent_72%)]"
            style={{
              width: ripple.size,
              height: ripple.size,
              left: ripple.x - ripple.size / 2,
              top: ripple.y - ripple.size / 2,
            }}
            initial={{ scale: 0.1, opacity: 0.55 }}
            animate={{ scale: 1, opacity: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: duration / 1000, ease: [0.16, 1, 0.3, 1] }}
          />
        ))}
      </AnimatePresence>

      <AnimatePresence mode="wait">
        {prefersReducedMotion ? (
          <motion.span
            key={flashKey}
            className="pointer-events-none absolute inset-0 bg-cyan-200/10"
            initial={{ opacity: 0 }}
            animate={{ opacity: [0, 0.5, 0] }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.18, ease: "easeOut" }}
          />
        ) : null}
      </AnimatePresence>

      <span className="relative z-10 flex items-center gap-3">
        <span className="h-2 w-2 rounded-full bg-cyan-200/80" />
        <span>{label}</span>
      </span>
    </motion.button>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { motion, useReducedMotion, type HTMLMotionProps } from "motion/react";

export interface CopyChipButtonProps
  extends Omit<HTMLMotionProps<"button">, "children"> {
  textToCopy?: string;
  idleLabel?: string;
  copiedLabel?: string;
  resetAfter?: number;
}

export function CopyChipButton({
  textToCopy = "motion-gallery://micro-interaction",
  idleLabel = "Copy",
  copiedLabel = "Copied",
  resetAfter = 1800,
  disabled = false,
  className = "",
  ...props
}: CopyChipButtonProps) {
  const prefersReducedMotion = useReducedMotion() ?? false;
  const [copied, setCopied] = useState(false);
  const timeoutRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        window.clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const handleCopy = async () => {
    if (disabled) {
      return;
    }

    if (timeoutRef.current) {
      window.clearTimeout(timeoutRef.current);
    }

    setCopied(true);

    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(textToCopy);
      }
    } catch {
      // Optimistic UI is the primary feedback path for this demo.
    }

    timeoutRef.current = window.setTimeout(() => {
      setCopied(false);
      timeoutRef.current = null;
    }, resetAfter);
  };

  return (
    <motion.button
      type="button"
      aria-label={copied ? copiedLabel : idleLabel}
      disabled={disabled}
      onClick={handleCopy}
      className={`relative inline-flex min-h-12 items-center gap-3 overflow-hidden rounded-full border px-4 py-2 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cyan-200/80 focus-visible:ring-offset-4 focus-visible:ring-offset-slate-950 disabled:cursor-not-allowed disabled:opacity-45 ${
        copied
          ? "border-emerald-300/40 bg-emerald-300/12 text-emerald-50"
          : "border-white/12 bg-white/[0.04] text-zinc-100 hover:bg-white/[0.08]"
      } ${className}`}
      whileTap={disabled ? undefined : { scale: 0.97 }}
      transition={{ type: "spring", stiffness: 320, damping: 24 }}
      {...props}
    >
      <span className="relative h-5 w-[5.8rem] overflow-hidden text-left">
        {prefersReducedMotion ? (
          <span>{copied ? copiedLabel : idleLabel}</span>
        ) : (
          <>
            <motion.span
              className="absolute inset-0"
              animate={{
                y: copied ? "-135%" : "0%",
                opacity: copied ? 0 : 1,
              }}
              transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}
            >
              {idleLabel}
            </motion.span>
            <motion.span
              className="absolute inset-0"
              animate={{
                y: copied ? "0%" : "135%",
                opacity: copied ? 1 : 0,
              }}
              transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}
            >
              {copiedLabel}
            </motion.span>
          </>
        )}
      </span>

      <span className="relative h-5 w-5">
        {prefersReducedMotion ? (
          copied ? (
            <svg viewBox="0 0 20 20" className="h-5 w-5" fill="none" aria-hidden="true">
              <path
                d="M4 10.5L8 14.5L16 6.5"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          ) : (
            <svg viewBox="0 0 20 20" className="h-5 w-5" fill="none" aria-hidden="true">
              <path
                d="M7 7.5V5.5C7 4.4 7.9 3.5 9 3.5H13C14.1 3.5 15 4.4 15 5.5V11.5C15 12.6 14.1 13.5 13 13.5H11"
                stroke="currentColor"
                strokeWidth="1.7"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <rect
                x="5"
                y="7.5"
                width="8"
                height="9"
                rx="2"
                stroke="currentColor"
                strokeWidth="1.7"
              />
            </svg>
          )
        ) : copied ? (
          <motion.svg
            viewBox="0 0 20 20"
            className="h-5 w-5"
            fill="none"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            aria-hidden="true"
          >
            <motion.path
              d="M4 10.5L8 14.5L16 6.5"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              initial={{ pathLength: 0 }}
              animate={{ pathLength: 1 }}
              transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}
            />
          </motion.svg>
        ) : (
          <svg viewBox="0 0 20 20" className="h-5 w-5" fill="none" aria-hidden="true">
            <path
              d="M7 7.5V5.5C7 4.4 7.9 3.5 9 3.5H13C14.1 3.5 15 4.4 15 5.5V11.5C15 12.6 14.1 13.5 13 13.5H11"
              stroke="currentColor"
              strokeWidth="1.7"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <rect
              x="5"
              y="7.5"
              width="8"
              height="9"
              rx="2"
              stroke="currentColor"
              strokeWidth="1.7"
            />
          </svg>
        )}
      </span>
    </motion.button>
  );
}

"use client";

import { useState, type MouseEvent } from "react";
import { motion, useReducedMotion, type HTMLMotionProps } from "motion/react";

type AccentTone = "rose" | "amber" | "cyan";

const accentStyles: Record<
  AccentTone,
  {
    shell: string;
    text: string;
    iconSurface: string;
    outline: string;
    fill: string;
    particle: string;
    glow: string;
    ring: string;
  }
> = {
  rose: {
    shell:
      "border-rose-200/18 bg-[linear-gradient(135deg,rgba(251,113,133,0.22),rgba(15,23,42,0.88))]",
    text: "text-rose-50",
    iconSurface:
      "bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.26),rgba(244,63,94,0.2)_54%,rgba(15,23,42,0.85))]",
    outline: "rgba(255,228,230,0.88)",
    fill: "#fb7185",
    particle: "rgba(251,113,133,0.95)",
    glow: "rgba(251,113,133,0.38)",
    ring: "rgba(255,228,230,0.26)",
  },
  amber: {
    shell:
      "border-amber-200/18 bg-[linear-gradient(135deg,rgba(251,191,36,0.2),rgba(15,23,42,0.88))]",
    text: "text-amber-50",
    iconSurface:
      "bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.24),rgba(245,158,11,0.2)_56%,rgba(15,23,42,0.85))]",
    outline: "rgba(254,243,199,0.9)",
    fill: "#f59e0b",
    particle: "rgba(251,191,36,0.95)",
    glow: "rgba(245,158,11,0.34)",
    ring: "rgba(253,230,138,0.24)",
  },
  cyan: {
    shell:
      "border-cyan-200/18 bg-[linear-gradient(135deg,rgba(34,211,238,0.2),rgba(15,23,42,0.9))]",
    text: "text-cyan-50",
    iconSurface:
      "bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.24),rgba(14,165,233,0.2)_56%,rgba(15,23,42,0.86))]",
    outline: "rgba(224,242,254,0.88)",
    fill: "#22d3ee",
    particle: "rgba(103,232,249,0.96)",
    glow: "rgba(34,211,238,0.34)",
    ring: "rgba(186,230,253,0.22)",
  },
};

const heartPath =
  "M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5C2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3C19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z";

export interface LikeBurstButtonProps
  extends Omit<HTMLMotionProps<"button">, "children"> {
  idleLabel?: string;
  likedLabel?: string;
  defaultLiked?: boolean;
  burstDensity?: number;
  accent?: AccentTone;
}

function createParticles(burstDensity: number) {
  const count = Math.max(6, Math.round(burstDensity));

  return Array.from({ length: count }, (_, index) => {
    const angle = (index / count) * Math.PI * 2 - Math.PI / 2;
    const lane = index % 3;
    const distance = 24 + lane * 10;
    const streak = index % 4 === 0;

    return {
      x: Math.cos(angle) * distance,
      y: Math.sin(angle) * distance,
      width: streak ? 12 : lane === 0 ? 6 : 4,
      height: streak ? 3 : lane === 0 ? 6 : 4,
      delay: lane * 0.018 + (index % 2) * 0.012,
      rotate: (angle * 180) / Math.PI,
    };
  });
}

export function LikeBurstButton({
  idleLabel = "Save",
  likedLabel = "Saved",
  defaultLiked = false,
  burstDensity = 12,
  accent = "rose",
  disabled = false,
  className = "",
  onClick,
  ...props
}: LikeBurstButtonProps) {
  const prefersReducedMotion = useReducedMotion() ?? false;
  const [liked, setLiked] = useState(defaultLiked);
  const [burstKey, setBurstKey] = useState(0);
  const [lastAction, setLastAction] = useState<"like" | "unlike">(
    defaultLiked ? "like" : "unlike"
  );
  const styles = accentStyles[accent];
  const particles = createParticles(burstDensity);

  const handleToggle = (event: MouseEvent<HTMLButtonElement>) => {
    if (disabled) {
      return;
    }

    const nextLiked = !liked;
    setLiked(nextLiked);
    setLastAction(nextLiked ? "like" : "unlike");

    if (nextLiked && !prefersReducedMotion) {
      setBurstKey((value) => value + 1);
    }

    onClick?.(event);
  };

  const isActive = liked && !disabled;

  return (
    <motion.button
      {...props}
      type="button"
      aria-pressed={liked}
      disabled={disabled}
      onClick={handleToggle}
      className={`group relative inline-flex min-h-16 items-center gap-4 overflow-hidden rounded-full border px-4 py-3 text-left shadow-[0_24px_64px_-40px_rgba(15,23,42,0.9)] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/80 focus-visible:ring-offset-4 focus-visible:ring-offset-slate-950 disabled:cursor-not-allowed disabled:opacity-45 ${styles.shell} ${styles.text} ${className}`}
      animate={{
        boxShadow: isActive
          ? `0 30px 72px -34px ${styles.glow}`
          : "0 24px 64px -40px rgba(15,23,42,0.9)",
        scale: disabled ? 1 : isActive ? 1.01 : 1,
      }}
      whileTap={disabled ? undefined : { scale: 0.97 }}
      transition={{ type: "spring", stiffness: 340, damping: 24 }}
    >
      <span
        className="absolute inset-0 opacity-80"
        style={{
          background: isActive
            ? `radial-gradient(circle at 20% 10%, ${styles.glow}, transparent 42%)`
            : "radial-gradient(circle at 20% 10%, rgba(255,255,255,0.08), transparent 42%)",
        }}
      />

      <span className="relative z-10 flex items-center gap-4">
        <motion.span
          initial={false}
          animate={
            liked
              ? { scale: [1, 1.18, 1], rotate: [0, -8, 6, 0] }
              : lastAction === "unlike"
                ? { scale: [1, 0.94, 1], rotate: [0, 4, 0] }
                : { scale: 1, rotate: 0 }
          }
          transition={{
            duration: liked ? 0.42 : 0.28,
            ease: [0.16, 1, 0.3, 1],
          }}
          className="relative grid h-11 w-11 place-items-center rounded-full border border-white/12"
        >
          <span className={`absolute inset-0 rounded-full ${styles.iconSurface}`} />
          <motion.span
            className="absolute inset-[-8px] rounded-full"
            initial={false}
            animate={{
              opacity: liked ? 1 : 0.45,
              scale: liked ? 1.08 : 0.92,
            }}
            transition={{ duration: 0.24, ease: [0.16, 1, 0.3, 1] }}
            style={{
              boxShadow: `0 0 0 1px ${styles.ring}`,
              background: prefersReducedMotion
                ? `radial-gradient(circle, ${styles.glow}, transparent 72%)`
                : `radial-gradient(circle, ${styles.glow}, transparent 66%)`,
            }}
          />

          {!prefersReducedMotion
            ? particles.map((particle, index) => (
                <motion.span
                  key={`${burstKey}-${index}`}
                  className="pointer-events-none absolute left-1/2 top-1/2 rounded-full"
                  style={{
                    width: particle.width,
                    height: particle.height,
                    backgroundColor: styles.particle,
                  }}
                  initial={{ x: -particle.width / 2, y: -particle.height / 2, opacity: 0, scale: 0.2 }}
                  animate={
                    liked
                      ? {
                          x: -particle.width / 2 + particle.x,
                          y: -particle.height / 2 + particle.y,
                          opacity: [0, 1, 0],
                          scale: [0.2, 1, 0.7],
                          rotate: particle.rotate,
                        }
                      : {
                          x: -particle.width / 2,
                          y: -particle.height / 2,
                          opacity: 0,
                          scale: 0.2,
                          rotate: particle.rotate,
                        }
                  }
                  transition={{
                    duration: 0.46,
                    delay: particle.delay,
                    ease: [0.16, 1, 0.3, 1],
                  }}
                />
              ))
            : null}

          <motion.svg
            viewBox="0 0 24 24"
            aria-hidden="true"
            className="relative z-10 h-5 w-5 overflow-visible"
            initial={false}
            animate={{ scale: liked ? 1.04 : 1 }}
            transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}
          >
            <motion.path
              d={heartPath}
              fill={styles.fill}
              initial={false}
              animate={{ opacity: liked ? 1 : 0.08, scale: liked ? 1 : 0.86 }}
              transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}
              style={{ transformOrigin: "center" }}
            />
            <path
              d={heartPath}
              fill="none"
              stroke={styles.outline}
              strokeWidth="1.7"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </motion.svg>
        </motion.span>

        <span className="flex min-w-[7rem] flex-col">
          <span className="text-[11px] uppercase tracking-[0.28em] text-white/45">
            Favorite
          </span>
          <span className="relative mt-1 h-6 overflow-hidden text-base font-semibold">
            {prefersReducedMotion ? (
              <span>{liked ? likedLabel : idleLabel}</span>
            ) : (
              <>
                <motion.span
                  className="absolute inset-0"
                  initial={false}
                  animate={{ y: liked ? "-120%" : "0%", opacity: liked ? 0 : 1 }}
                  transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
                >
                  {idleLabel}
                </motion.span>
                <motion.span
                  className="absolute inset-0"
                  initial={false}
                  animate={{ y: liked ? "0%" : "120%", opacity: liked ? 1 : 0 }}
                  transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
                >
                  {likedLabel}
                </motion.span>
              </>
            )}
          </span>
        </span>
      </span>
    </motion.button>
  );
}

"use client";

import type { HTMLAttributes, ReactNode } from "react";
import { useMemo, useRef } from "react";
import {
  motion,
  useMotionTemplate,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";

function cn(...values: Array<string | undefined>) {
  return values.filter(Boolean).join(" ");
}

interface CenterPeekCardSpringConfig {
  stiffness: number;
  damping: number;
  mass: number;
}

interface CenterPeekCardPeekConfig {
  width: number;
  height: number;
  borderRadius: number;
  translateY: number;
  scale: number;
  opacity: number;
}

export const CENTER_PEEK_CARD_DEFAULTS = {
  scrollHeight: 2.4,
  settleThreshold: 0.42,
  containerPadding: 40,
  peek: {
    width: 760,
    height: 48,
    borderRadius: 32,
    translateY: 180,
    scale: 0.94,
    opacity: 0.75,
  },
  spring: {
    stiffness: 170,
    damping: 26,
    mass: 0.6,
  },
} as const;

export interface CenterPeekCardProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  children: ReactNode;
  shellClassName?: string;
  cardClassName?: string;
  glowClassName?: string;
  padding?: number;
  scrollHeight?: number;
  settleThreshold?: number;
  peek?: Partial<CenterPeekCardPeekConfig>;
  spring?: Partial<CenterPeekCardSpringConfig>;
}

export function CenterPeekCard({
  children,
  className,
  shellClassName,
  cardClassName,
  glowClassName,
  padding,
  scrollHeight,
  settleThreshold,
  peek,
  spring,
  style,
  ...props
}: CenterPeekCardProps) {
  const prefersReducedMotion = useReducedMotion() ?? false;
  const containerRef = useRef<HTMLElement>(null);

  const resolvedPeek = useMemo(
    () => ({ ...CENTER_PEEK_CARD_DEFAULTS.peek, ...peek }),
    [peek]
  );
  const resolvedSpring = useMemo(
    () => ({ ...CENTER_PEEK_CARD_DEFAULTS.spring, ...spring }),
    [spring]
  );
  const resolvedPadding = padding ?? CENTER_PEEK_CARD_DEFAULTS.containerPadding;
  const resolvedScrollHeight = scrollHeight ?? CENTER_PEEK_CARD_DEFAULTS.scrollHeight;
  const rawSettleThreshold = settleThreshold ?? CENTER_PEEK_CARD_DEFAULTS.settleThreshold;
  const resolvedSettleThreshold = Math.min(Math.max(rawSettleThreshold, 0.05), 0.95);

  const settledDimensions = useMemo(
    () => ({
      width: `calc(100vw - ${resolvedPadding * 2}px)`,
      height: `calc(100vh - ${resolvedPadding * 2}px)`,
      borderRadius: Math.max(36 - resolvedPadding * 0.1, 16),
    }),
    [resolvedPadding]
  );

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"],
  });

  const sizeProgress = useTransform(
    scrollYProgress,
    [0, resolvedSettleThreshold],
    [0, 1]
  );
  const smoothSizeProgress = useSpring(sizeProgress, resolvedSpring);

  const width = useMotionTemplate`calc(${resolvedPeek.width}px + (100vw - ${resolvedPadding * 2}px - ${resolvedPeek.width}px) * ${smoothSizeProgress})`;
  const height = useMotionTemplate`calc(${resolvedPeek.height}vh + (100vh - ${resolvedPadding * 2}px - ${resolvedPeek.height}vh) * ${smoothSizeProgress})`;

  const borderRadius = useTransform(
    scrollYProgress,
    [0, resolvedSettleThreshold],
    [resolvedPeek.borderRadius, settledDimensions.borderRadius]
  );

  const y = useTransform(
    scrollYProgress,
    [0, resolvedSettleThreshold],
    [resolvedPeek.translateY, 0]
  );

  const scale = useTransform(
    scrollYProgress,
    [0, resolvedSettleThreshold],
    [resolvedPeek.scale, 1]
  );

  const opacity = useTransform(
    scrollYProgress,
    [0, resolvedSettleThreshold],
    [resolvedPeek.opacity, 1]
  );

  const glowOpacity = useTransform(
    scrollYProgress,
    [0, resolvedSettleThreshold],
    [0.15, 0.42]
  );

  const smoothY = useSpring(y, resolvedSpring);
  const smoothScale = useSpring(scale, resolvedSpring);
  const smoothOpacity = useSpring(opacity, resolvedSpring);
  const smoothGlowOpacity = useSpring(glowOpacity, resolvedSpring);

  const sectionStyle = prefersReducedMotion
    ? style
    : { ...style, height: `${resolvedScrollHeight * 100}vh` };

  if (prefersReducedMotion) {
    return (
      <section className={className} style={sectionStyle} {...props}>
        <div
          className={cn(
            "relative flex min-h-screen items-center justify-center overflow-hidden",
            shellClassName
          )}
          style={{ padding: resolvedPadding }}
        >
          <div
            className={cn(
              "absolute left-1/2 top-1/2 h-[32rem] w-[32rem] -translate-x-1/2 -translate-y-1/2 rounded-full bg-orange-500/25 blur-3xl",
              glowClassName
            )}
          />
          <div
            className={cn(
              "relative min-h-[24rem] min-w-[18rem] overflow-hidden shadow-[0_32px_120px_rgba(0,0,0,0.45)]",
              cardClassName
            )}
            style={{
              width: settledDimensions.width,
              height: settledDimensions.height,
              borderRadius: settledDimensions.borderRadius,
            }}
          >
            {children}
          </div>
        </div>
      </section>
    );
  }

  return (
    <section ref={containerRef} className={className} style={sectionStyle} {...props}>
      <div
        className={cn(
          "sticky top-0 flex h-screen items-center justify-center overflow-hidden",
          shellClassName
        )}
        style={{ padding: resolvedPadding }}
      >
        <motion.div
          className={cn(
            "absolute left-1/2 top-1/2 h-[32rem] w-[32rem] -translate-x-1/2 -translate-y-1/2 rounded-full bg-orange-500/30 blur-3xl",
            glowClassName
          )}
          style={{ opacity: smoothGlowOpacity }}
        />
        <motion.div
          className={cn(
            "relative min-w-[18rem] overflow-hidden shadow-[0_32px_120px_rgba(0,0,0,0.45)]",
            cardClassName
          )}
          style={{
            width,
            height,
            borderRadius,
            y: smoothY,
            scale: smoothScale,
            opacity: smoothOpacity,
            originY: 1,
          }}
        >
          {children}
        </motion.div>
      </div>
    </section>
  );
}

'use client'

/**
 * CenterPeekShrinkCard - A two-phase scroll-driven card animation
 *
 * Phase 1 (GROW):   Card expands from a small "peek" state to full viewport
 * Phase 2 (SHRINK): Card collapses to a compact header anchored at the top
 */

import {
  type MotionValue,
  motion,
  useMotionTemplate,
  useReducedMotion,
  useScroll,
  useSpring,
  useTransform,
} from 'motion/react'
import type { ReactNode } from 'react'
import { useMemo, useRef } from 'react'

// =============================================================================
// SHARED CONFIG (inlined from peek-cards/configs.ts)
// =============================================================================

const CENTER_PEEK_SHRINK_CONFIG = {
  scrollHeight: 10.5,
  settleThreshold: 0.22,
  shrinkThreshold: 0.22,
  containerPadding: 40,
  peek: {
    width: 760,
    height: 48,
    borderRadius: 32,
    translateY: 180,
    scale: 0.94,
    opacity: 0.75,
  },
  shrink: {
    targetHeight: 300,
    targetBorderRadius: 20,
  },
  spring: {
    stiffness: 170,
    damping: 26,
    mass: 0.6,
  },
} as const

// Re-export config for consumers who reference it
export const CENTER_PEEK_SHRINK_CONFIG_EXPORT = CENTER_PEEK_SHRINK_CONFIG

// ============================================================================
// COMPONENT PROPS
// ============================================================================

export interface CenterPeekShrinkCardProps {
  children: ReactNode
  className?: string
  shellClassName?: string
  cardClassName?: string
  padding?: number
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export function CenterPeekShrinkCard({
  children,
  className,
  shellClassName,
  cardClassName,
  padding = CENTER_PEEK_SHRINK_CONFIG.containerPadding,
}: CenterPeekShrinkCardProps) {
  const prefersReducedMotion = useReducedMotion()
  const containerRef = useRef<HTMLDivElement>(null)

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ['start end', 'end start'],
  })

  const settledDimensions = useMemo(
    () => ({
      width: `calc(100vw - ${padding * 2}px)`,
      height: `calc(100vh - ${padding * 2}px)`,
      borderRadius: Math.max(36 - padding * 0.1, 16),
    }),
    [padding],
  )

  // Phase 1: GROW
  const growProgress = useTransform(
    scrollYProgress,
    [0, CENTER_PEEK_SHRINK_CONFIG.settleThreshold],
    [0, 1],
  )
  const smoothGrowProgress = useSpring(
    growProgress as MotionValue<number>,
    CENTER_PEEK_SHRINK_CONFIG.spring,
  )

  // Phase 2: SHRINK
  const shrinkProgress = useTransform(
    scrollYProgress,
    [CENTER_PEEK_SHRINK_CONFIG.settleThreshold, 0.5, 1],
    [0, 1, 1],
  )
  const smoothShrinkProgress = useSpring(
    shrinkProgress as MotionValue<number>,
    CENTER_PEEK_SHRINK_CONFIG.spring,
  )

  // Width (grow only)
  const width = useMotionTemplate`calc(${CENTER_PEEK_SHRINK_CONFIG.peek.width}px + (100vw - ${padding * 2}px - ${CENTER_PEEK_SHRINK_CONFIG.peek.width}px) * ${smoothGrowProgress})`

  // Height (two-phase: grow then shrink)
  const fullHeight = `calc(100vh - ${padding * 2}px)`
  const peekHeight = `${CENTER_PEEK_SHRINK_CONFIG.peek.height}vh`
  const collapsedHeight = `${CENTER_PEEK_SHRINK_CONFIG.shrink.targetHeight}px`
  const growHeight = useMotionTemplate`calc(${peekHeight} + (${fullHeight} - ${peekHeight}) * ${smoothGrowProgress})`
  const height = useMotionTemplate`calc(${growHeight} - (${fullHeight} - ${collapsedHeight}) * ${smoothShrinkProgress})`

  // Border radius
  const borderRadius = useTransform(
    scrollYProgress,
    [0, CENTER_PEEK_SHRINK_CONFIG.settleThreshold, 1],
    [
      CENTER_PEEK_SHRINK_CONFIG.peek.borderRadius,
      settledDimensions.borderRadius,
      CENTER_PEEK_SHRINK_CONFIG.shrink.targetBorderRadius,
    ],
  )

  // Y stays centered
  const y = useTransform(scrollYProgress, [0, 1], [0, 0])
  const scale = useTransform(
    scrollYProgress,
    [0, CENTER_PEEK_SHRINK_CONFIG.settleThreshold],
    [CENTER_PEEK_SHRINK_CONFIG.peek.scale, 1],
  )
  const opacity = useTransform(
    scrollYProgress,
    [0, CENTER_PEEK_SHRINK_CONFIG.settleThreshold],
    [CENTER_PEEK_SHRINK_CONFIG.peek.opacity, 1],
  )
  const glowOpacity = useTransform(
    scrollYProgress,
    [0, CENTER_PEEK_SHRINK_CONFIG.settleThreshold, 1],
    [0.15, 0.42, 0.2],
  )

  const smoothY = useSpring(y as MotionValue<number>, CENTER_PEEK_SHRINK_CONFIG.spring)
  const smoothScale = useSpring(scale as MotionValue<number>, CENTER_PEEK_SHRINK_CONFIG.spring)
  const smoothOpacity = useSpring(opacity as MotionValue<number>, CENTER_PEEK_SHRINK_CONFIG.spring)
  const smoothGlowOpacity = useSpring(
    glowOpacity as MotionValue<number>,
    CENTER_PEEK_SHRINK_CONFIG.spring,
  )
  const smoothBorderRadius = useSpring(
    borderRadius as MotionValue<number>,
    CENTER_PEEK_SHRINK_CONFIG.spring,
  )

  if (prefersReducedMotion) {
    return (
      <section className={className}>
        <div
          className={`relative flex min-h-screen items-start justify-center overflow-hidden ${shellClassName ?? ''}`}
          style={{ padding }}
        >
          <div className="absolute left-1/2 top-1/2 h-[32rem] w-[32rem] -translate-x-1/2 -translate-y-1/2 rounded-full bg-orange-500/20 blur-3xl" />
          <div
            className={`relative min-h-[24rem] min-w-[18rem] overflow-hidden shadow-[0_32px_120px_rgba(0,0,0,0.45)] ${cardClassName ?? ''}`}
            style={{
              width: settledDimensions.width,
              height: settledDimensions.height,
              borderRadius: settledDimensions.borderRadius,
            }}
          >
            {children}
          </div>
        </div>
      </section>
    )
  }

  return (
    <section
      ref={containerRef}
      data-testid="center-peek-shrink-card"
      className={className}
      style={{ height: `${CENTER_PEEK_SHRINK_CONFIG.scrollHeight * 100}vh` }}
    >
      <div
        className={`sticky top-0 flex h-screen items-start justify-center overflow-hidden ${shellClassName ?? ''}`}
        style={{ padding }}
      >
        <motion.div
          className="absolute left-1/2 top-1/2 h-[32rem] w-[32rem] -translate-x-1/2 -translate-y-1/2 rounded-full bg-orange-500/30 blur-3xl"
          style={{ opacity: smoothGlowOpacity }}
        />
        <motion.div
          data-testid="center-peek-shrink-card-inner"
          className={`relative min-w-[18rem] overflow-hidden shadow-[0_32px_120px_rgba(0,0,0,0.45)] ${cardClassName ?? ''}`}
          style={{
            width,
            height,
            borderRadius: smoothBorderRadius,
            y: smoothY,
            scale: smoothScale,
            opacity: smoothOpacity,
            originY: 0,
          }}
        >
          {children}
        </motion.div>
      </div>
    </section>
  )
}

