            {value === "" && demoState === "idle" && (
              <motion.span
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute text-zinc-400 pointer-events-none text-sm"
              >
