// AIMessage
// ============================================

interface AIMessageProps {
  message: string;
  subheader?: string;
  isTyping?: boolean;
  typingSpeed?: number;
  onTypingComplete?: () => void;
  className?: string;
}

export function AIMessage({
  message,
  subheader = "AI Assistant",
  isTyping = false,
  typingSpeed = 30,
  onTypingComplete,
  className = "",
}: AIMessageProps) {
  const [displayedText, setDisplayedText] = useState("");
  const [isComplete, setIsComplete] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    let frameId: ReturnType<typeof window.requestAnimationFrame> | undefined;

    if (!isTyping) {
      frameId = window.requestAnimationFrame(() => {
        setDisplayedText(message);
        setIsComplete(true);
      });

      return () => {
        if (frameId) {
          window.cancelAnimationFrame(frameId);
        }
      };
    }

    frameId = window.requestAnimationFrame(() => {
      setDisplayedText("");
      setIsComplete(false);
    });

    let currentIndex = 0;

    const typeNextChar = () => {
      if (currentIndex < message.length) {
        setDisplayedText(message.slice(0, currentIndex + 1));
        currentIndex++;
        timeoutRef.current = setTimeout(typeNextChar, typingSpeed);
      } else {
        setIsComplete(true);
        onTypingComplete?.();
      }
    };

    timeoutRef.current = setTimeout(typeNextChar, typingSpeed);

    return () => {
      if (frameId) {
        window.cancelAnimationFrame(frameId);
      }
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [message, isTyping, typingSpeed, onTypingComplete]);

  return (
    <motion.div
      initial={{ x: -20, opacity: 0 }}
      animate={{ x: 0, opacity: 1 }}
      transition={{ ...CHAT_SPRING_PRESETS.gentle }}
      className={`flex flex-col gap-1 ${className}`}
    >
      <span className="text-xs text-zinc-500">{subheader}</span>
      <div className="text-sm text-zinc-800 leading-relaxed">
        {displayedText}
        {isTyping && !isComplete && (
          <motion.span
            animate={{ opacity: [1, 0] }}
            transition={{ duration: 0.5, repeat: Infinity }}
            className="inline-block w-0.5 h-4 bg-zinc-800 ml-0.5 align-middle"
          />
        )}
      </div>
    </motion.div>
  );
}

